package com.complaintbox.service;
import com.complaintbox.dto.ComplaintDtos.*; import com.complaintbox.entity.*; import com.complaintbox.exception.ApiException; import com.complaintbox.repository.*; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service public class ComplaintService { public final ComplaintRepository repo; final CategoryRepository cats; final ResidentRepository residents; final StaffRepository staff; final ComplaintHistoryRepository history; final NotificationRepository notifications;
 public ComplaintService(ComplaintRepository r,CategoryRepository c,ResidentRepository res,StaffRepository s,ComplaintHistoryRepository h,NotificationRepository n){repo=r;cats=c;residents=res;staff=s;history=h;notifications=n;}
 public Complaint create(Long rid,Create in){Resident r=residents.findById(rid).orElseThrow(()->new ApiException("Resident not found"));Category cat=cats.findByName(in.category()).orElseThrow(()->new ApiException("Category not found"));Complaint c=new Complaint();c.setComplaintId("HC-"+LocalDate.now().getYear()+"-"+UUID.randomUUID().toString().substring(0,7).toUpperCase());c.setResident(r);c.setCategory(cat);c.setTitle(in.title().trim());c.setDescription(in.description().trim());c.setRoomNumber(in.roomNumber().trim());c.setHostelBlock(in.hostelBlock().trim());c.setPriority(Complaint.Priority.valueOf(in.priority().toUpperCase()));c.setStatus(ComplaintStatus.SUBMITTED);c.setImageUrl(in.imageUrl());c.setAdditionalInfo(in.additionalInfo());Complaint saved=repo.save(c);addHistory(saved,rid,"Complaint created",null,"submitted",in.title());notifyResident(r,null,saved,"complaint_submitted","Complaint submitted",saved.getComplaintId()+" is now in the warden queue.");for(Staff w:staff.findAll())if(w.getRole()==StaffRole.WARDEN)notifyStaff(w,saved,"new_complaint","New complaint received",saved.getComplaintId()+" · "+saved.getTitle());return saved;}
 public List<Complaint> mine(Long rid){Resident r=residents.findById(rid).orElseThrow();return repo.findByResidentOrderByCreatedAtDesc(r);} public Complaint get(Long id){return repo.findById(id).orElseThrow(()->new ApiException("Complaint not found"));}
 public Map<String,Object> detail(Long id){Complaint c=get(id);Map<String,Object> m=new LinkedHashMap<>();m.put("complaint",map(c));List<Map<String,Object>> hs=new ArrayList<>();for(ComplaintHistory h:history.findByComplaintOrderByCreatedAtDesc(c)){Map<String,Object> x=new LinkedHashMap<>();x.put("id",h.getId());x.put("action",h.getAction());x.put("note",h.getNote());x.put("createdAt",h.getCreatedAt());hs.add(x);}m.put("history",hs);if(c.getAssignedStaff()!=null){Map<String,Object> s=new LinkedHashMap<>();s.put("id",c.getAssignedStaff().getId());s.put("name",c.getAssignedStaff().getName());s.put("specialty",c.getAssignedStaff().getSpecialty());m.put("assignedStaff",s);}else m.put("assignedStaff",null);Map<String,Object> st=new LinkedHashMap<>();st.put("name",c.getResident().getName());st.put("email",c.getResident().getEmail());st.put("studentId",c.getResident().getResidentId());m.put("student",st);return m;}
 @Transactional public Complaint update(Long staffId,Long id,Status in){Complaint c=get(id);Staff actor=staff.findById(staffId).orElseThrow();ComplaintStatus old=c.getStatus();ComplaintStatus next=ComplaintStatus.valueOf(in.status().toUpperCase());if(next.ordinal()<old.ordinal()&&(in.wardenRemarks()==null||in.wardenRemarks().isBlank()))throw new ApiException("A remark is required when moving a complaint backward.");if(in.assignedStaffId()!=null)c.setAssignedStaff(staff.findById(in.assignedStaffId()).orElseThrow(()->new ApiException("Assigned staff not found")));else if(in.assignedStaffId()==null&&old==ComplaintStatus.SUBMITTED&&next==ComplaintStatus.ASSIGNED){throw new ApiException("Assign a maintenance staff member before marking assigned.");}if(in.title()!=null)c.setTitle(in.title());if(in.description()!=null)c.setDescription(in.description());if(in.priority()!=null)c.setPriority(Complaint.Priority.valueOf(in.priority().toUpperCase()));c.setStatus(next);if(in.wardenRemarks()!=null)c.setWardenRemarks(in.wardenRemarks());if(next==ComplaintStatus.RESOLVED)c.setResolvedAt(LocalDateTime.now());else if(next!=ComplaintStatus.RESOLVED)c.setResolvedAt(null);Complaint saved=repo.save(c);if(old!=next){addHistory(saved,staffId,"Status changed to "+next.name().toLowerCase().replace('_',' '),old.name().toLowerCase(),next.name().toLowerCase(),null);notifyResident(c.getResident(),c.getAssignedStaff(),c,"status_changed","Complaint status updated",c.getComplaintId()+" is now "+next.name().toLowerCase().replace('_',' ')+".");}if(in.assignedStaffId()!=null){addHistory(saved,staffId,"Assigned to "+c.getAssignedStaff().getName(),null,null,c.getAssignedStaff().getName());notifyResident(c.getResident(),c.getAssignedStaff(),c,"complaint_assigned","Complaint assignment updated",c.getComplaintId()+" has been assigned for follow-up.");}if(in.wardenRemarks()!=null&&!in.wardenRemarks().isBlank()){addHistory(saved,staffId,"Warden added a remark",null,null,in.wardenRemarks());notifyResident(c.getResident(),c.getAssignedStaff(),c,"warden_remark","New warden remark","A warden added an update to "+c.getComplaintId()+".");}return saved;}
 public Map<String,Object> dashboard(){List<Complaint> rows=repo.findAll();Map<String,Object> s=new LinkedHashMap<>();s.put("total",rows.size());s.put("new",rows.stream().filter(x->x.getStatus()==ComplaintStatus.SUBMITTED).count());s.put("assigned",rows.stream().filter(x->x.getStatus()==ComplaintStatus.ASSIGNED).count());s.put("inProgress",rows.stream().filter(x->x.getStatus()==ComplaintStatus.IN_PROGRESS).count());s.put("resolved",rows.stream().filter(x->x.getStatus()==ComplaintStatus.RESOLVED).count());s.put("rejected",rows.stream().filter(x->x.getStatus()==ComplaintStatus.REJECTED).count());List<Map<String,Object>> recent=repo.findAllByOrderByCreatedAtDesc().stream().limit(8).map(this::map).toList();return Map.of("stats",s,"recent",recent);}
 public List<Map<String,Object>> allMapped(){return repo.findAllByOrderByCreatedAtDesc().stream().map(this::map).toList();}
 public Map<String,Object> map(Complaint c){Map<String,Object> m=new LinkedHashMap<>();m.put("id",c.getId());m.put("complaintId",c.getComplaintId());m.put("title",c.getTitle());m.put("description",c.getDescription());m.put("category",c.getCategory().getName());m.put("categoryId",c.getCategory().getId());m.put("roomNumber",c.getRoomNumber());m.put("hostelBlock",c.getHostelBlock());m.put("priority",c.getPriority().name().toLowerCase());m.put("status",c.getStatus().name().toLowerCase());m.put("imageUrl",c.getImageUrl());m.put("additionalInfo",c.getAdditionalInfo());m.put("wardenRemarks",c.getWardenRemarks());m.put("createdAt",c.getCreatedAt());m.put("updatedAt",c.getUpdatedAt());m.put("resolvedAt",c.getResolvedAt());m.put("overdue",c.isOverdue());m.put("assignedStaffId",c.getAssignedStaff()==null?null:c.getAssignedStaff().getId());if(c.getAssignedStaff()!=null){Map<String,Object>s=new LinkedHashMap<>();s.put("id",c.getAssignedStaff().getId());s.put("name",c.getAssignedStaff().getName());s.put("specialty",c.getAssignedStaff().getSpecialty());s.put("active",c.getAssignedStaff().isActive());m.put("assignedStaff",s);}else m.put("assignedStaff",null);Map<String,Object> st=new LinkedHashMap<>();st.put("name",c.getResident().getName());st.put("email",c.getResident().getEmail());st.put("studentId",c.getResident().getResidentId());m.put("student",st);return m;}
 void addHistory(Complaint c,Long actor,String action,String from,String to,String note){ComplaintHistory h=new ComplaintHistory();h.setComplaint(c);h.setActorUserId(actor);h.setAction(action);h.setFromStatus(from);h.setToStatus(to);h.setNote(note);history.save(h);}void notifyResident(Resident r,Staff s,Complaint c,String type,String title,String body){Notification n=new Notification();n.setResident(r);n.setStaff(null);n.setComplaintId(c.getId());n.setType(type);n.setTitle(title);n.setBody(body);n.setRead(false);notifications.save(n);}void notifyStaff(Staff s,Complaint c,String type,String title,String body){Notification n=new Notification();n.setStaff(s);n.setComplaintId(c.getId());n.setType(type);n.setTitle(title);n.setBody(body);n.setRead(false);notifications.save(n);}
 @Scheduled(fixedDelay=3600000) @Transactional public void overdue(){LocalDateTime cutoff=LocalDateTime.now().minusDays(5);for(Complaint c:repo.findAll()){boolean x=c.getStatus()!=ComplaintStatus.RESOLVED&&c.getCreatedAt()!=null&&c.getCreatedAt().isBefore(cutoff);if(c.isOverdue()!=x){c.setOverdue(x);repo.save(c);}}}
}
